mapper.select:
SELECT * FROM com_sales_order_line
WHERE tenant_id = #{query.tenantId}
  AND source_system = #{query.sourceSystem}
  AND source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT l.* FROM com_sales_order_line l
WHERE l.tenant_id = #{query.tenantId} AND l.deleted = 0
  AND (

    CAST(l.company_code AS BINARY) IN
    CAST(#{companyCode} AS BINARY)

   OR 

    EXISTS (SELECT 1 FROM com_order_contract_relation ocr
            JOIN com_project_contract_relation pcr ON pcr.tenant_id = ocr.tenant_id
             AND pcr.contract_id = ocr.contract_id AND pcr.deleted = 0
             AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL
           WHERE ocr.tenant_id = l.tenant_id AND ocr.order_id = l.order_id AND ocr.deleted = 0
             AND pcr.project_id IN
             #{projectId})

  )

  AND l.order_id = #{query.orderId}

AND CAST(l.company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND l.order_type = #{query.orderType}
AND l.order_no = #{query.orderNo}
AND l.line_no = #{query.lineNo}
AND l.item_code = #{query.itemCode}
AND l.product_code = #{query.productCode}
AND l.quantity_status = #{query.quantityStatus}
AND l.status = #{query.status}
ORDER BY l.order_id, l.line_no, l.id
LIMIT #{query.offset}, #{query.limit}

SELECT * FROM com_sales_order_line
WHERE tenant_id = #{query.tenantId}
  AND deleted = 0
  AND id IN

      #{orderLineId}

ORDER BY id ASC

SELECT COUNT(*) FROM com_sales_order_line l
WHERE l.tenant_id = #{query.tenantId} AND l.deleted = 0
  AND (

    CAST(l.company_code AS BINARY) IN
    CAST(#{companyCode} AS BINARY)

   OR 

    EXISTS (SELECT 1 FROM com_order_contract_relation ocr
            JOIN com_project_contract_relation pcr ON pcr.tenant_id = ocr.tenant_id
             AND pcr.contract_id = ocr.contract_id AND pcr.deleted = 0
             AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL
           WHERE ocr.tenant_id = l.tenant_id AND ocr.order_id = l.order_id AND ocr.deleted = 0
             AND pcr.project_id IN
             #{projectId})

  )

  AND l.order_id = #{query.orderId}

AND CAST(l.company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)
AND l.order_type = #{query.orderType}
AND l.order_no = #{query.orderNo}
AND l.line_no = #{query.lineNo}
AND l.item_code = #{query.itemCode}
AND l.product_code = #{query.productCode}
AND l.quantity_status = #{query.quantityStatus}
AND l.status = #{query.status}

SELECT * FROM com_sales_order_line WHERE tenant_id = #{query.tenantId} AND deleted = 0 AND id IN
#{orderLineId}
ORDER BY id ASC FOR UPDATE
